fn read_record(file: &mut File) -> Result<Record, Box<dyn Error>> {
    let mut buf = [0; 4];
    file.read_exact(&mut buf)?;
    let age = u32::from_le_bytes(buf);

    let mut buf = [0; 4];
    file.read_exact(&mut buf)?;
    let height = f32::from_le_bytes(buf);

    let mut name_buf = Vec::new();
    file.read_to_end(&mut name_buf)?;
    let name = String::from_utf8(name_buf)?;

    Ok(Record { name, age, height })
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut file = File::open("data.bin")?;

    while let Ok(record) = read_record(&mut file) {
        println!("Name: {}, Age: {}, Height: {}", record.name, record.age, record.height);
    }

    Ok(())
}
```

