function calculateAverage(numbersArray) {
  // Initialize variables to keep track of the sum and count
  let sum = 0;
  let count = 0;

  // Iterate through the array to calculate the sum and count of numeric values
  for (let I = 0; I < numbersArray.length; i++) {
    // Check if the current value is a number
    if (typeof numbersArray[i] === "number" && !isNaN(numbersArray[i])) {
      sum += numbersArray[i];
      count++;
    }
  }

  // Calculate the average and return it
  if (count > 0) {
    return sum / count;
  } else {
    return 0;
  }
}

