program HeronFormula;

var
  side1, side2, side3, s, area: real;

begin
  writeln('Enter the three sides of the triangle:');
  readln(side1, side2, side3);

  // Check for negative or impossible values
  if (side1 <= 0) or (side2 <= 0) or (side3 <= 0) or ((side1 + side2 <= side3) or (side1 + side3 <= side2) or (side2 + side3 <= side1)) then
  begin
    writeln('Invalid values for triangle sides!');
    halt;
  end;

  // Calculate semi-perimeter
  s := (side1 + side2 + side3) / 2;

  // Calculate area using Heron's formula
  area := sqrt(s * (s - side1) * (s - side2) * (s - side3));

  // Display area rounded to two decimal places
  writeln('Area of the triangle is: ', format('%0.2f', [area]));
end.
```

Explanation of the code:

